const NOW = Date.now();
const SEED_POSTS = [
  {
    id:'p1', authorId:'u1', text:'¡Bienvenidos a ConnectSpace! Aquí compartiremos novedades, logros y todo lo que nos une como equipo. 🚀 Cuéntenme: ¿cuál es su meta para este trimestre?',
